CREATE INDEX "pending_action_expiry_scoped_idx" ON "pending_action" USING btree ("expires_at","id") WHERE (state = 'pending'::text) AND ((workspace_id IS NOT NULL) OR ((workspace_id IS NULL) AND (project_id IS NULL) AND (organisation_id IS NULL) AND (((action = 'delete'::text) AND (target_type = 'user'::text) AND (route_key = 'POST /api/instance/users/{id}/deactivate'::text)) OR ((action = 'user_deactivation'::text) AND (target_type = 'person'::text) AND (route_key = 'POST /api/instance/users/{id}/deactivate'::text)))));--> statement-breakpoint
CREATE INDEX "pending_action_expiry_unscoped_probe_idx" ON "pending_action" USING btree ("expires_at") WHERE (state = 'pending'::text) AND (workspace_id IS NULL) AND (NOT (((project_id IS NULL) AND (organisation_id IS NULL) AND (((action = 'delete'::text) AND (target_type = 'user'::text) AND (route_key = 'POST /api/instance/users/{id}/deactivate'::text)) OR ((action = 'user_deactivation'::text) AND (target_type = 'person'::text) AND (route_key = 'POST /api/instance/users/{id}/deactivate'::text))))))
